        "openai:default":    {"type": "api_key", "key": "sk-..."}
                           | {"type": "oauth", "access": "...", "refresh": "...", "expires": 1234567890},
        "google:default":    {"type": "oauth", "access": "...", "refresh": "...", "expires": 1234567890},
        "deepseek:default":  {"type": "api_key", "key": "sk-..."}
    }
}
"""

import json
import logging
import time
from pathlib import Path

from core.encryption import decrypt_dict, encrypt_dict, needs_migration
from core.storage import atomic_write_json

logger = logging.getLogger(__name__)

DATA_DIR = Path(__file__).parent.parent.parent / "data"
PROFILES_PATH = DATA_DIR / "auth-profiles.json"

# Last-resort fallback when no model is specified. _resolved_default_model()
# (below) prefers the inferred "top" tier from model-tiers.json when available.
PROVIDER_DEFAULTS = {
    "anthropic": "claude-opus-4-8",
    "openai": "gpt-5.4",
    "deepseek": "deepseek-v4-flash",
    "google": "gemini-2.5-flash",
    "ollama": "",
    "together": "Qwen/Qwen3.5-9B",
}


def _resolved_default_model(provider: str) -> str:
    """Default model when none is specified: the inferred/resolved 'top' tier if
    materialized, else the hardcoded PROVIDER_DEFAULTS. Keeps fresh connections
    pointed at a current model even outside the connect-flow inference path."""
    try:
        from core.providers.model_tiers import get_resolved
        top = get_resolved(provider).get("top")
        if top:
            return top
    except Exception:
        pass
    return PROVIDER_DEFAULTS.get(provider, "")


class CredentialStore:
    def __init__(self):
        self.data = self._load()

    def _load(self) -> dict:
        if PROFILES_PATH.exists():
            try:
                raw = json.loads(PROFILES_PATH.read_text(encoding="utf-8"))
                decrypted = decrypt_dict(raw)
                # Auto-migrate plaintext credentials to encrypted on disk
                if needs_migration(raw):
                    logger.info("Migrating auth-profiles.json to encrypted storage")
                    self.data = decrypted
                    self._save()
                return decrypted
            except Exception as e:
                logger.error("Failed to load auth-profiles.json: %s", e)
        return {"active_provider": "", "active_model": "", "profiles": {}}

    def _save(self):
        encrypted = encrypt_dict(self.data)
        atomic_write_json(PROFILES_PATH, encrypted)

    def get_active_profile(self, provider_override: str | None = None) -> tuple[str, dict | None]:
        """Return (profile_name, profile_dict) for the active (or overridden) provider."""
        provider = provider_override or self.data.get("active_provider", "")
        if not provider:
            return ("", None)

        profile_name = f"{provider}:default"
        profile = self.data.get("profiles", {}).get(profile_name)
        return (profile_name, profile)

    def get_google_token(self) -> str:
        """Return the current Google OAuth access token (no refresh logic here)."""
        profile = self.data.get("profiles", {}).get("google:default", {})
        return profile.get("access", "")

    def is_configured(self) -> bool:
        """Return True if at least one provider has valid credentials."""
        profiles = self.data.get("profiles", {})
        for name, p in profiles.items():
            if p.get("type") == "api_key" and p.get("key"):
                return True
            if p.get("type") == "oauth" and p.get("access"):
                return True
            if p.get("type") == "setup_token" and p.get("token"):
                return True
            if p.get("type") == "chatgpt_oauth" and p.get("access"):
                return True
            if p.get("type") == "ollama_local" and p.get("base_url"):
                return True
        return False

    def set_chatgpt_oauth(
        self,
        access_token: str,
        refresh_token: str,
        expires_in: int,
        model: str | None = None,
    ):
        """Store ChatGPT OAuth tokens (from Codex CLI) and set OpenAI as active."""
        if "profiles" not in self.data:
            self.data["profiles"] = {}
        self.data["profiles"]["openai:default"] = {
            "type": "chatgpt_oauth",
            "access": access_token,
            "refresh": refresh_token,
            "expires": int(time.time()) + expires_in,
        }
        self.data["active_provider"] = "openai"
        self.data["active_model"] = model or _resolved_default_model("openai")
        self._save()

    def set_setup_token(self, provider: str, token: str, model: str | None = None):
        """Store a setup-token (e.g. from `claude setup-token`) and set as active."""
        profile_name = f"{provider}:default"
        if "profiles" not in self.data:
            self.data["profiles"] = {}
        self.data["profiles"][profile_name] = {"type": "setup_token", "token": token}
        self.data["active_provider"] = provider
        self.data["active_model"] = model or _resolved_default_model(provider)
        self._save()

    def set_api_key(self, provider: str, key: str, model: str | None = None):
        """Store an API key for the given provider.

        Becomes the active provider only when none is set yet (first-run
        setup). Adding an additional provider's key — e.g. a Gemini key just
        for meeting transcription — must not hijack the active chat provider;
        switching providers is an explicit action (the set-active endpoint).
        """
        profile_name = f"{provider}:default"
        if "profiles" not in self.data:
            self.data["profiles"] = {}
        self.data["profiles"][profile_name] = {"type": "api_key", "key": key}
        if not self.data.get("active_provider"):
            self.data["active_provider"] = provider
            self.data["active_model"] = model or _resolved_default_model(provider)
        self._save()

    def set_oauth_tokens(
        self,
        provider: str,
        access_token: str,
        refresh_token: str,
        expires_in: int,
        model: str | None = None,
        set_active: bool = True,
    ):
        """Store OAuth tokens for the given provider.

        When set_active=False, only the token is written — active_provider /
        active_model are untouched. Use this when the tokens are being stored
        for a non-AI purpose (e.g. Gmail/Calendar/Drive integration) and the
        user may have a different AI provider selected.

        If an existing refresh_token is present and the caller passes an empty
        one, the existing value is preserved. (Google omits refresh_token on
        re-auth when the user had already granted offline access.)
        """
        profile_name = f"{provider}:default"
        if "profiles" not in self.data:
            self.data["profiles"] = {}

        existing = self.data["profiles"].get(profile_name, {})
        effective_refresh = refresh_token or existing.get("refresh", "")

        self.data["profiles"][profile_name] = {
            "type": "oauth",
            "access": access_token,
            "refresh": effective_refresh,
            "expires": int(time.time()) + expires_in,
        }
        if set_active:
            self.data["active_provider"] = provider
            self.data["active_model"] = model or _resolved_default_model(provider)
        self._save()

    def set_active_model(self, model: str):
        """Update the active model."""
        if model and model != "default":
            self.data["active_model"] = model
        else:
            provider = self.data.get("active_provider", "")
            self.data["active_model"] = _resolved_default_model(provider)
        self._save()

    def set_active_provider(self, provider: str):
        """Switch active provider (must already have credentials stored)."""
        self.data["active_provider"] = provider
        if not self.data.get("active_model"):
            self.data["active_model"] = _resolved_default_model(provider)
        self._save()

    def remove_provider(self, provider: str):
        """Remove credentials for a provider."""
        profile_name = f"{provider}:default"
        self.data.get("profiles", {}).pop(profile_name, None)
        if self.data.get("active_provider") == provider:
            self.data["active_provider"] = ""
            self.data["active_model"] = ""
        self._save()

