"""
Chatty — AI provider factory.

Returns the active AIProvider based on credentials in data/auth-profiles.json.
"""

from core.providers.base import AIProvider
from core.providers.credentials import CredentialStore


def get_ai_provider(
    agent_provider: str | None = None,
    agent_model: str | None = None,
    agent_model_tier: str | None = None,
) -> AIProvider | None:
    """
    Return an initialized AIProvider for the active (or specified) provider.

    Args:
        agent_provider: Optional per-agent provider override ("anthropic", "openai", "google").
        agent_model: Optional per-agent model override (takes precedence over tier).
        agent_model_tier: Optional tier ("auto", "top", "mid", "light").
            For "auto", resolves to "top" here (triage runs separately in _stream_chat).

    Returns None if no provider is configured.
    """
    store = CredentialStore()
    profile_name, profile = store.get_active_profile(provider_override=agent_provider)

    if not profile:
        return None

    # Resolve model: agent_model > tier > global active_model
    if agent_model:
        raw_model = agent_model
    elif agent_model_tier:
        from core.providers.model_tiers import has_explicit_tier
        from core.providers.tiers import resolve_tier_model
        provider_key = agent_provider or store.data.get("active_provider", "")
        tier = "top" if agent_model_tier == "auto" else agent_model_tier
        active_model = store.data.get("active_model", "")
        active_provider = store.data.get("active_provider", "")
        if has_explicit_tier(provider_key, tier):
            raw_model = resolve_tier_model(provider_key, tier) or ""
        elif tier == "top" and active_model and provider_key == active_provider:
            # Fresh deploy / no tiers materialized yet: respect the user's
            # configured active_model instead of the hardcoded TIER_MODELS
            # constant, so a PR that bumps the constant can't silently swap the
            # model used by background runs. mid/light keep the hardcoded
            # fallback (they were never the user's explicit pick).
            raw_model = active_model
        else:
            raw_model = resolve_tier_model(provider_key, tier) or ""
    else:
        raw_model = store.data.get("active_model", "")
    model = raw_model if raw_model and raw_model != "default" else ""

    if profile_name.startswith("anthropic:"):
        from core.providers.anthropic_provider import AnthropicProvider
        if profile.get("type") == "setup_token":
            return AnthropicProvider(api_key=profile.get("token", ""), model=model or "claude-opus-4-8")
        return AnthropicProvider(api_key=profile.get("key", ""), model=model or "claude-opus-4-8")

    elif profile_name.startswith("openai:"):
        from core.providers.openai_provider import OpenAIProvider
        if profile.get("type") == "api_key":
            return OpenAIProvider(access_token=profile.get("key", ""), model=model or "gpt-5.4")
        if profile.get("type") == "chatgpt_oauth":
            access_token = profile.get("access", "")
            # Refresh token if expired
            if store.is_token_expired("openai"):
                try:
                    import asyncio
                    from core.providers.chatgpt_refresh import refresh_chatgpt_token
                    tokens = asyncio.get_event_loop().run_until_complete(
                        refresh_chatgpt_token(profile.get("refresh", ""))
                    )
                    access_token = tokens["access_token"]
                    store.set_chatgpt_oauth(
                        access_token=tokens["access_token"],
                        refresh_token=tokens["refresh_token"],
                        expires_in=tokens["expires_in"],
                        model=model or "gpt-5.4",
                    )
                except Exception as e:
                    import logging
                    logging.getLogger(__name__).warning("ChatGPT token refresh failed: %s", e)
            return OpenAIProvider(access_token=access_token, model=model or "gpt-5.4", use_chatgpt_api=True)
        access_token = profile.get("access", "")
        return OpenAIProvider(access_token=access_token, model=model or "gpt-5.4", use_chatgpt_api=True)

    elif profile_name.startswith("deepseek:"):
        from core.providers.deepseek_provider import DeepSeekProvider
        if profile.get("type") == "api_key":
            return DeepSeekProvider(access_token=profile.get("key", ""), model=model or "deepseek-v4-flash")
        access_token = profile.get("access", "")
        return DeepSeekProvider(access_token=access_token, model=model or "deepseek-v4-flash")

    elif profile_name.startswith("kimi:"):
        from core.providers.kimi_provider import KimiProvider

        if profile.get("type") == "api_key":
            return KimiProvider(
                access_token=profile.get("key", ""),
                model=model or "kimi-k3"
            )

        access_token = profile.get("access", "")
        return KimiProvider(
            access_token=access_token,
            model=model or "kimi-k3"
        )

    elif profile_name.startswith("google:"):
        from core.providers.google_provider import GoogleProvider
        if profile.get("type") == "api_key":
            return GoogleProvider(api_key=profile.get("key", ""), model=model or "gemini-2.5-flash")
        access_token = profile.get("access", "")
        return GoogleProvider(access_token=access_token, model=model or "gemini-2.5-flash")

    elif profile_name.startswith("ollama:"):
        from core.providers.ollama_provider import OllamaProvider
        base_url = profile.get("base_url", "http://localhost:11434")
        return OllamaProvider(base_url=base_url, model=model or "")

    elif profile_name.startswith("together:"):
        from core.providers.together_provider import TogetherProvider
        return TogetherProvider(api_key=profile.get("key", ""), model=model or "Qwen/Qwen3.5-9B")

    return None

"""Chatty — Auto-triage classifier.

Routes messages to the appropriate model tier using:
1. Heuristic fast-path (greetings/acks -> light)
2. Provider-specific classifier (three-way top/mid/light, biased toward top)
3. Per-conversation upward-only cache
"""

from __future__ import annotations

import logging
from collections import OrderedDict

from core.providers.credentials import CredentialStore
from core.providers.tiers import get_triage_classifier

logger = logging.getLogger(__name__)

_TRIAGE_GREETINGS = frozenset({
    "hi", "hey", "hello", "good morning", "good afternoon", "good evening",
    "morning", "afternoon", "evening", "howdy", "sup", "yo", "hiya",
    "whats up", "what's up", "greetings",
})

_TRIAGE_ACKS = frozenset({
    "thanks", "thank you", "thx", "ty", "great", "perfect", "awesome",
    "got it", "ok", "okay", "cool", "sounds good", "nice", "sweet",
})

_TIER_RANK = {"light": 0, "mid": 1, "top": 2}

_MAX_CACHE_SIZE = 500
_conversation_tier_cache: OrderedDict[str, str] = OrderedDict()

_TRIAGE_SYSTEM_PROMPT = (
    "Classify this message. Reply with ONLY one word: TOP, MID, or LIGHT.\n\n"
    "TOP — complex reasoning, analysis, planning, creative work, code generation, "
    "multi-step tasks, anything requiring deep understanding or nuance. "
    "When in doubt, choose TOP.\n"
    "MID — summarization, simple explanations, Q&A with context, formatting, translation.\n"
    "LIGHT — simple greetings, acknowledgments, yes/no questions, trivial lookups."
)

_MAX_INPUT_CHARS = 500


def _should_fast_path_light(text: str) -> bool:
    normalized = text.strip().lower().rstrip("!.?,;:")
    return normalized in _TRIAGE_GREETINGS or normalized in _TRIAGE_ACKS


def _cache_get(conversation_id: str) -> str | None:
    tier = _conversation_tier_cache.get(conversation_id)
    if tier is not None:
        _conversation_tier_cache.move_to_end(conversation_id)
    return tier


def _cache_set(conversation_id: str, tier: str) -> None:
    _conversation_tier_cache[conversation_id] = tier
    _conversation_tier_cache.move_to_end(conversation_id)
    while len(_conversation_tier_cache) > _MAX_CACHE_SIZE:
        _conversation_tier_cache.popitem(last=False)


def _max_tier(a: str, b: str) -> str:
    return a if _TIER_RANK.get(a, -1) >= _TIER_RANK.get(b, -1) else b


def _parse_tier(raw: str) -> str:
    upper = raw.strip().upper()
    if "LIGHT" in upper:
        return "light"
    if "MID" in upper:
        return "mid"
    return "top"


def extract_classifier_credentials(provider: str, store: CredentialStore) -> dict:
    """Extract the right credentials for the triage classifier, matching get_ai_provider() logic."""
    _, profile = store.get_active_profile(provider_override=provider)
    if not profile:
        return {}

    if provider == "anthropic":
        if profile.get("type") == "setup_token":
            return {"api_key": profile.get("token", "")}
        return {"api_key": profile.get("key", "")}

    elif provider == "openai":
        if profile.get("type") == "api_key":
            return {"api_key": profile.get("key", "")}
        if profile.get("type") == "chatgpt_oauth":
            return {"api_key": profile.get("access", ""), "use_chatgpt_api": True}
        return {"api_key": profile.get("access", "")}

    elif provider == "google":
        if profile.get("type") == "api_key":
            return {"api_key": profile.get("key", "")}
        return {"access_token": profile.get("access", "")}

    return {}


_CLASSIFIER_TIMEOUT = 5


async def _classify_anthropic(text: str, creds: dict) -> str:
    import anthropic
    client = anthropic.AsyncAnthropic(api_key=creds["api_key"], timeout=_CLASSIFIER_TIMEOUT)
    response = await client.messages.create(
        model=get_triage_classifier("anthropic"),
        max_tokens=5,
        system=_TRIAGE_SYSTEM_PROMPT,
        messages=[{"role": "user", "content": text[:_MAX_INPUT_CHARS]}],
    )
    return response.content[0].text


async def _classify_openai(text: str, creds: dict) -> str:
    import openai
    kwargs: dict = {"api_key": creds["api_key"], "timeout": _CLASSIFIER_TIMEOUT}
    if creds.get("use_chatgpt_api"):
        from core.providers.openai_provider import CHATGPT_PROXY_URL
        kwargs["base_url"] = CHATGPT_PROXY_URL
    client = openai.AsyncOpenAI(**kwargs)
    response = await client.chat.completions.create(
        model=get_triage_classifier("openai"),
        max_completion_tokens=20,
        messages=[
            {"role": "system", "content": _TRIAGE_SYSTEM_PROMPT},
            {"role": "user", "content": text[:_MAX_INPUT_CHARS]},
        ],
    )
    return response.choices[0].message.content or ""


async def _classify_google(text: str, creds: dict) -> str:
    import asyncio
    import google.generativeai as genai
    if creds.get("api_key"):
        genai.configure(api_key=creds["api_key"])
    elif creds.get("access_token"):
        genai.configure(credentials=_google_oauth_creds(creds["access_token"]))
    model = genai.GenerativeModel(
        get_triage_classifier("google"),
        system_instruction=_TRIAGE_SYSTEM_PROMPT,
    )
    response = await asyncio.wait_for(
        model.generate_content_async(
            text[:_MAX_INPUT_CHARS],
            generation_config=genai.types.GenerationConfig(max_output_tokens=5),
        ),
        timeout=_CLASSIFIER_TIMEOUT,
    )
    return response.text or ""


def _google_oauth_creds(access_token: str):
    from google.oauth2.credentials import Credentials
    return Credentials(token=access_token)


_CLASSIFY_DISPATCH = {
    "anthropic": _classify_anthropic,
    "openai":    _classify_openai,
    "google":    _classify_google,
}


async def classify_tier(
    user_message: str,
    provider: str,
    credentials: dict,
    conversation_id: str | None = None,
    has_attachments: bool = False,
) -> tuple[str, str]:
    """Classify a message into a model tier.

    Returns (tier, method) where tier is "top"/"mid"/"light"
    and method is "heuristic"/"classifier"/"cached"/"skip".
    """
    if has_attachments:
        return ("top", "skip")

    # Upward-only cache check
    cached_tier = None
    if conversation_id:
        cached_tier = _cache_get(conversation_id)

    if _should_fast_path_light(user_message):
        tier = "light"
        if cached_tier:
            tier = _max_tier(cached_tier, tier)
        if conversation_id:
            _cache_set(conversation_id, tier)
        return (tier, "heuristic")

    # If cached, promote upward only
    classify_fn = _CLASSIFY_DISPATCH.get(provider)
    if not classify_fn or (not credentials.get("api_key") and not credentials.get("access_token")):
        return ("top", "skip")

    try:
        raw = await classify_fn(user_message, credentials)
        tier = _parse_tier(raw)
        if cached_tier:
            tier = _max_tier(cached_tier, tier)
        if conversation_id:
            _cache_set(conversation_id, tier)
        return (tier, "classifier")
    except Exception as e:
        logger.warning("Triage classifier failed for %s, defaulting to top: %s", provider, e)
        return ("top", "skip")

"""
Chatty — Shared agent router factory.

Creates a FastAPI router with chat + context + conversation endpoints.
Used by the multi-agent system (agents/router.py) to mount per-agent routes.

No voice endpoints. No Odoo/tool-confirmation flow.
"""

from fastapi import APIRouter, Depends, HTTPException
from fastapi.responses import StreamingResponse
from pydantic import BaseModel

from core.auth import get_current_user
from core.providers import get_ai_provider
from core.providers.credentials import CredentialStore
from .config import AgentConfig
from .context_manager import ContextManager
from .tool_registry import ToolRegistry
from .chat_history.service import ChatHistoryService
from . import ai_service


# ── Request models ────────────────────────────────────────────────────────────

class ChatRequest(BaseModel):
    messages: list[dict]
    conversation_id: str | None = None
    training_mode: bool = False


class ContextWriteRequest(BaseModel):
    content: str


class UpdateTitleRequest(BaseModel):
    title: str


# ── Filename safety ───────────────────────────────────────────────────────────

def _safe_filename(filename: str) -> bool:
    if not filename or not filename.endswith(".md"):
        return False
    if "/" in filename or "\\" in filename or ".." in filename:
        return False
    return True


# ── Factory ───────────────────────────────────────────────────────────────────

def create_agent_router(
    config: AgentConfig,
    ctx_manager: ContextManager,
    chat_service: ChatHistoryService | None = None,
    integration_tool_defs: list[dict] | None = None,
) -> APIRouter:
    """Create a FastAPI router for a single agent.

    The router is intended to be mounted at /api/agents/{agent_id}/ by
    the multi-agent router. It does NOT include the /api/agents prefix itself.

    Args:
        config: Agent configuration
        ctx_manager: Per-agent context file manager
        chat_service: Optional chat history service (enables /conversations endpoints)
        integration_tool_defs: Extra tool definitions from enabled integrations
    """
    router = APIRouter()

    # ── Chat (SSE) ────────────────────────────────────────────────────

    @router.post("/chat")
    async def chat(req: ChatRequest, user=Depends(get_current_user)):
        store = CredentialStore()
        provider = get_ai_provider(
            agent_provider=config.provider_override or None,
            agent_model=config.model_override or None,
            agent_model_tier=config.model_tier,
        )
        if not provider:
            raise HTTPException(status_code=400, detail="No AI provider configured")

        ga = config.google_accounts
        gmail_ids = ga.get("gmail", [])
        calendar_ids = ga.get("calendar", [])
        drive_ids = ga.get("drive", [])
        google_connected = bool(gmail_ids or calendar_ids or drive_ids)

        from integrations.registry import list_google_accounts as _list_ga
        all_ga = _list_ga()
        account_info_map = {
            aid: {"email": a.get("email", ""), "scope_grants": a.get("scope_grants", {}), "connection_status": a.get("connection_status", "ok")}
            for aid, a in all_ga.items()
        }

        registry = ToolRegistry(
            context_dir=config.context_dir,
            google_connected=google_connected,
            gmail_account_ids=gmail_ids,
            calendar_account_ids=calendar_ids,
            drive_account_ids=drive_ids,
            account_info_map=account_info_map,
        )

        # Anthropic API key for smart title generation (haiku)
        _, anthropic_profile = store.get_active_profile(provider_override="anthropic")
        anthropic_api_key = (anthropic_profile or {}).get("api_key", "")

        async def event_generator():
            async for event in ai_service.chat(
                config=config,
                provider=provider,
                registry=registry,
                ctx_manager=ctx_manager,
                messages=req.messages,
                training_mode=req.training_mode,
                conversation_id=req.conversation_id,
                chat_service=chat_service,
                anthropic_api_key=anthropic_api_key,
                integration_tool_defs=integration_tool_defs,
            ):
                yield event

        return StreamingResponse(
            event_generator(),
            media_type="text/event-stream",
            headers={
                "Cache-Control": "no-cache",
                "Connection": "keep-alive",
                "X-Accel-Buffering": "no",
            },
        )

    # ── Onboarding progress ───────────────────────────────────────────

    @router.get("/onboarding/progress")
    def onboarding_progress(user=Depends(get_current_user)):
        content = ctx_manager.read_context("_onboarding-progress.md")
        if not content:
            return {"topics": [], "completed": 0, "total": 0}

        topics = []
        for line in content.splitlines():
            stripped = line.strip()
            if stripped.startswith("- [x]"):
                topics.append({"name": stripped[6:].strip(), "status": "done"})
            elif stripped.startswith("- [~]"):
                topics.append({"name": stripped[6:].strip(), "status": "skipped"})
            elif stripped.startswith("- [ ]"):
                topics.append({"name": stripped[6:].strip(), "status": "pending"})

        done = sum(1 for t in topics if t["status"] == "done")
        return {"topics": topics, "completed": done, "total": len(topics)}

    # ── Context CRUD ──────────────────────────────────────────────────

    @router.get("/context")
    def list_context(user=Depends(get_current_user)):
        return {"files": ctx_manager.list_context_files()}

    @router.get("/context/{filename}")
    def get_context(filename: str, user=Depends(get_current_user)):
        if not _safe_filename(filename):
            raise HTTPException(status_code=400, detail="Invalid filename")
        content = ctx_manager.read_context(filename)
        if not content and not (ctx_manager.data_dir / filename).exists():
            raise HTTPException(status_code=404, detail="File not found")
        return {"filename": filename, "content": content}

    @router.put("/context/{filename}")
    def put_context(filename: str, req: ContextWriteRequest, user=Depends(get_current_user)):
        if not _safe_filename(filename):
            raise HTTPException(status_code=400, detail="Invalid filename")
        ctx_manager.write_context(filename, req.content)
        return {"filename": filename, "ok": True}

    @router.delete("/context/{filename}")
    def delete_context(filename: str, user=Depends(get_current_user)):
        if not _safe_filename(filename):
            raise HTTPException(status_code=400, detail="Invalid filename")
        if not ctx_manager.delete_context(filename):
            raise HTTPException(status_code=404, detail="File not found")
        return {"filename": filename, "deleted": True}

    # ── Conversations (when chat_service provided) ────────────────────

    if chat_service is not None:

        @router.get("/conversations/search")
        def search_conversations(q: str = "", user=Depends(get_current_user)):
            if not q.strip():
                return {"results": []}
            return {"results": chat_service.search_conversations(q.strip())}

        @router.get("/conversations")
        def list_conversations(limit: int = 50, offset: int = 0, user=Depends(get_current_user)):
            return {"conversations": chat_service.list_conversations(limit, offset)}

        @router.post("/conversations")
        def create_conversation(user=Depends(get_current_user)):
            return chat_service.create_conversation()

        @router.get("/conversations/{conv_id}")
        def get_conversation(conv_id: str, user=Depends(get_current_user)):
            result = chat_service.get_conversation(conv_id)
            if not result:
                raise HTTPException(status_code=404, detail="Conversation not found")
            return result

        @router.delete("/conversations/{conv_id}")
        def delete_conversation(conv_id: str, user=Depends(get_current_user)):
            if not chat_service.delete_conversation(conv_id):
                raise HTTPException(status_code=404, detail="Conversation not found")
            return {"deleted": True}

        @router.patch("/conversations/{conv_id}/title")
        def update_conversation_title(
            conv_id: str, req: UpdateTitleRequest, user=Depends(get_current_user)
        ):
            new_title = chat_service.rename_conversation(conv_id, req.title)
            if new_title is None:
                raise HTTPException(status_code=404, detail="Conversation not found or title empty")
            return {"title": new_title}

    return router

"""Chatty — Model tier definitions, inference, and resolution.

Tier labels (top/mid/light) map to concrete model IDs per provider. The
mapping is resolved synchronously (resolve_tier_model) as override -> inferred
-> hardcoded fallback; see model_tiers.py. infer_tier_models() produces the
name-based default from a live model list (called from the async listing path).
"""

from __future__ import annotations

import re


# Hardcoded fallback only. Resolution order is override -> inferred -> this map
# (see resolve_tier_model / model_tiers.py). Kept current by the price-check skill.
TIER_MODELS: dict[str, dict[str, str]] = {
    "anthropic": {
        "top":   "claude-opus-4-8",
        "mid":   "claude-sonnet-4-6",
        "light": "claude-haiku-4-5",
    },
    "openai": {
        "top":   "gpt-5.5",
        "mid":   "gpt-5.4-mini",
        "light": "gpt-5.4-nano",
    },
    "deepseek": {
        "top": "deepseek-v4-pro",
        "mid": "deepseek-v4-flash",
        "light": "deepseek-v4-flash",
    },
    "google": {
        "top":   "gemini-2.5-pro",
        "mid":   "gemini-2.5-flash",
        "light": "gemini-2.5-flash-lite",
    },
    "together": {
        "top":   "meta-llama/Llama-3.3-70B-Instruct-Turbo",
        "mid":   "google/gemma-4-31B-it",
        "light": "Qwen/Qwen3.5-9B",
    },
}

# Fallback display labels. The /tiers endpoint derives labels from the resolved
# model ids; these are used only when no resolved id is available.
TIER_LABELS: dict[str, dict[str, str]] = {
    "anthropic": {"top": "Opus", "mid": "Sonnet", "light": "Haiku"},
    "openai":    {"top": "GPT-5.5", "mid": "Mini", "light": "Nano"},
    "deepseek":  {"top": "Pro","mid": "Flash","light": "Flash",},
    "google":    {"top": "Pro", "mid": "Flash", "light": "Flash-Lite"},
    "together":  {"top": "70B", "mid": "31B", "light": "9B"},
}

# Hardcoded fallback for the triage classifier (the cheap "light"-tier model).
# get_triage_classifier() prefers override/inferred and falls back to this.
TRIAGE_CLASSIFIERS: dict[str, str] = {
    "anthropic": "claude-haiku-4-5",
    "openai":    "gpt-5.4-nano",
    "deepseek":  "deepseek-v4-flash",
    "google":    "gemini-2.5-flash-lite",
}


# ── Name-based tier inference (pure; no I/O) ───────────────────────────────────

def _version_key(model: str) -> tuple[int, ...]:
    return tuple(int(n) for n in re.findall(r"\d+", model))


def _best(candidates: list[str]) -> str | None:
    """Pick the highest-version candidate (ties broken by string)."""
    if not candidates:
        return None
    return max(candidates, key=lambda m: (_version_key(m), m))


def infer_tier_models(provider: str, available: list[str]) -> dict[str, str]:
    """Best-guess {top, mid, light} from a live model list, by naming.

    Pure function — no I/O. Falls back per-tier to the hardcoded TIER_MODELS
    entry when no candidate matches. The async listing path calls this and
    persists the result via model_tiers.set_inferred (live fetches only).
    """
    fb = TIER_MODELS.get(provider, {})
    av = [m for m in (available or []) if m]
    top = mid = light = None

    if provider == "anthropic":
        top = _best([m for m in av if "opus" in m.lower()])
        mid = _best([m for m in av if "sonnet" in m.lower()])
        light = _best([m for m in av if "haiku" in m.lower()])
    elif provider == "google":
        # Only real Gemini chat models. The live catalog also lists specialty
        # models whose names collide with the tier keywords — deep-research-pro,
        # lyria-3-pro (music), nano-banana-pro (image), TTS/image/robotics/
        # computer-use variants — some of which claim generateContent support
        # in metadata but reject it at call time ("only supports Interactions
        # API"), which would brick every chat turn routed to that tier.
        _specialty = ("image", "tts", "robotics", "computer-use", "customtools")
        g = [m for m in av
             if m.lower().startswith("gemini-")
             and not any(t in m.lower() for t in _specialty)]
        top = _best([m for m in g if "pro" in m.lower()])
        light = _best([m for m in g if "lite" in m.lower()])
        mid = _best([m for m in g if "flash" in m.lower() and "lite" not in m.lower()])
    elif provider == "openai":
        light = _best([m for m in av if "-nano" in m.lower()])
        mid = _best([m for m in av if "-mini" in m.lower()])
        top = _best([
            m for m in av
            if "-mini" not in m.lower() and "-nano" not in m.lower()
            and (m.lower().startswith("gpt-") or m.lower().startswith("o"))
        ])
    elif provider == "deepseek":
        top = _best([m for m in av if "pro" in m.lower()])
        mid = _best([m for m in av if "flash" in m.lower()])
        light = mid
    elif provider == "together":
        def _params(m: str) -> int:
            nums = re.findall(r"(\d+)\s*b", m.lower())
            return int(nums[-1]) if nums else 0
        # Only rank models with a detectable size — otherwise an unsized,
        # possibly-large model (e.g. DeepSeek-V3) sorts to the cheap 'light' slot.
        sized = sorted([m for m in av if _params(m) > 0], key=_params, reverse=True)
        if sized:
            top = sized[0]
            light = sized[-1]
            # Avoid mid == light on a 2-model list (len//2 == 1 == last index).
            mid = sized[len(sized) // 2] if len(sized) > 2 else sized[0]

    chosen = {
        "top": top or fb.get("top", ""),
        "mid": mid or fb.get("mid", ""),
        "light": light or fb.get("light", ""),
    }
    # Never persist a tier whose model isn't actually in the live catalog: the
    # per-tier hardcoded fallback may name a model this account/catalog doesn't
    # expose, and auto-triage would then call a nonexistent model. Substitute a
    # model that IS available (the heuristic picks are members of `av`).
    if av:
        present = set(av)
        substitute = top or mid or light or av[0]
        for tier in chosen:
            if chosen[tier] and chosen[tier] not in present:
                chosen[tier] = substitute if substitute in present else av[0]
    return chosen


def infer_triage_classifier(provider: str, available: list[str]) -> str | None:
    """The cheap triage/classifier model = inferred 'light' tier."""
    return infer_tier_models(provider, available).get("light") or TRIAGE_CLASSIFIERS.get(provider)


# ── Synchronous resolution (override -> inferred -> hardcoded) ──────────────────

def resolve_tier_model(provider: str, tier: str) -> str | None:
    """Resolve a tier to a concrete model id. Synchronous by contract —
    callers (get_ai_provider, agents/router) run in sync context, so this reads
    the materialized model_tiers store and never lists models live."""
    from core.providers.model_tiers import get_resolved
    return get_resolved(provider).get(tier) or None


def _short_label(model_id: str) -> str:
    """Compact display label from a model id (Together 'org/Name' -> 'Name')."""
    return model_id.split("/")[-1] if model_id else ""


def derive_tier_labels(provider: str, resolved: dict[str, str] | None = None) -> dict[str, str]:
    """Display labels per tier, derived from the resolved model id, with
    TIER_LABELS as fallback. Always non-empty for a known provider so the
    frontend tier switcher never hides itself. Pass an already-loaded
    ``resolved`` map to avoid a redundant store read."""
    if resolved is None:
        from core.providers.model_tiers import get_resolved
        resolved = get_resolved(provider)
    fb = TIER_LABELS.get(provider, {})
    return {
        t: _short_label(resolved.get(t, "")) or fb.get(t, t.title())
        for t in ("top", "mid", "light")
    }


def supports_auto_triage(provider: str) -> bool:
    return provider in TRIAGE_CLASSIFIERS


def get_triage_classifier(provider: str) -> str | None:
    """The cheap classifier model: resolved 'light' tier, else hardcoded."""
    from core.providers.model_tiers import get_resolved
    light = get_resolved(provider).get("light")
    return light or TRIAGE_CLASSIFIERS.get(provider)

